<?php
use App\Modules\Users\Models\User;
use App\Services\TwoFactorService;
use App\Services\Totp;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Crypt;
// Included by two_factor.php after the existing lifecycle/email checks.
app('session')->driver()->invalidate();
app('cache')->store('array')->flush();
$requiredUser = User::create(['name' => 'Required enrollment', 'email' => 'required@example.invalid', 'password' => 'Example123!', 'is_active' => true, 'two_factor_required' => true]);
$beforeTokens = $requiredUser->tokens()->count();
$login = http2fa('/api/auth/login', 'POST', ['email' => $requiredUser->email, 'password' => 'Example123!']);
$body = json_decode($login->getContent(), true);
check($login->getStatusCode() === 202 && $body['enrollment_required'] && !isset($body['token']), 'required unenrolled mobile account receives enrollment challenge without access token');
check($requiredUser->tokens()->count() === $beforeTokens, 'password proof alone cannot issue credentials before mandatory enrollment');
$pending = $body['challenge_token'];
check(http2fa('/api/auth/two-factor/enroll', 'POST', ['method' => 'authenticator', 'challenge_token' => str_repeat('0',64)])->getStatusCode() === 422, 'enrollment rejects unrelated challenge');
$setup = http2fa('/api/auth/two-factor/enroll', 'POST', ['method' => 'authenticator', 'challenge_token' => $pending]);
$enrollment = json_decode($setup->getContent(), true);
check($setup->getStatusCode() === 200 && isset($enrollment['secret'], $enrollment['otpauth_uri']) && $enrollment['expires_in'] <= 300, 'password-verified owner can enroll an authenticator through mobile API');
$bad = http2fa('/api/auth/two-factor/challenge', 'POST', ['challenge_token' => $pending, 'code' => 'bad']);
check($bad->getStatusCode() === 422 && !app(TwoFactorService::class)->enabled($requiredUser), 'invalid enrollment code grants no access and does not confirm factor');
$verified = http2fa('/api/auth/two-factor/challenge', 'POST', ['challenge_token' => $pending, 'code' => app(Totp::class)->code($enrollment['secret'], intdiv(now()->timestamp,30))]);
$access = json_decode($verified->getContent(), true);
check($verified->getStatusCode() === 200 && isset($access['token']) && count($access['recovery_codes'] ?? []) === 10, 'required enrollment verifies factor before issuing token and one-time recovery set');
$disable = http2fa('/api/security/two-factor', 'POST', ['current_password' => 'Example123!', 'action' => 'disable', 'code' => $access['recovery_codes'][0]], $access['token']);
check($disable->getStatusCode() === 422 && app(TwoFactorService::class)->enabled($requiredUser), 'required user cannot disable an enrolled factor');
$switch = http2fa('/api/security/two-factor/setup', 'POST', ['current_password' => 'Example123!', 'replace' => true, 'method' => 'authenticator', 'code' => $access['recovery_codes'][0]], $access['token']);
$newSetup = json_decode($switch->getContent(), true);
check($switch->getStatusCode() === 200 && app(TwoFactorService::class)->enabled($requiredUser), 'verified method replacement preserves active factor during setup ('.$switch->getStatusCode().')');
$oldRow = DB::table('user_two_factor_settings')->where('user_id',$requiredUser->id)->first();
check(Crypt::decryptString($oldRow->secret) === $enrollment['secret'], 'pending replacement leaves original authenticator active');
$switched = http2fa('/api/security/two-factor', 'POST', ['current_password' => 'Example123!', 'action' => 'confirm', 'code' => app(Totp::class)->code($newSetup['secret'], intdiv(now()->timestamp,30))], $access['token']);
check($switched->getStatusCode() === 200 && Crypt::decryptString(DB::table('user_two_factor_settings')->where('user_id',$requiredUser->id)->value('secret')) === $newSetup['secret'], 'new method becomes active only after new code confirmation');
check(http2fa('/api/security/two-factor', 'GET', [], $access['token'])->getStatusCode() === 200, 'self-service security change preserves current mobile token');
$requiredUser->update(['two_factor_required'=>false]);
check(app(TwoFactorService::class)->enabled($requiredUser), 'removing admin requirement does not disable user-owned enrollment');
// Browser enrollment uses only the pending password-verified session.
$browserUser = User::create(['name'=>'Browser enrollment','email'=>'required-browser@example.invalid','password'=>'Example123!','is_active'=>true,'two_factor_required'=>true]);
app('session')->driver()->invalidate();
app('cache')->store('array')->flush();
$webCookies = [];
$browser = $web('/login', 'POST', ['email'=>$browserUser->email,'password'=>'Example123!','remember'=>1]);
check($browser->getStatusCode()===302 && str_ends_with($browser->headers->get('Location'),'/login/two-factor'), 'required browser account stops at enrollment');
$page=$web('/login/two-factor');
check($page->getStatusCode()===200 && str_contains($page->getContent(),'Set up two-step login'), 'browser enrollment page renders without authenticated application access');
$browserSetup = $web('/login/two-factor/enroll','POST',['method'=>'authenticator']);
check($browserSetup->getStatusCode()===302 && DB::table('user_two_factor_settings')->where('user_id',$browserUser->id)->value('pending_secret') !== null, 'browser owner starts authenticator enrollment ('.$browserSetup->getStatusCode().')');
$secret=Crypt::decryptString(DB::table('user_two_factor_settings')->where('user_id',$browserUser->id)->value('pending_secret'));
$complete=$web('/login/two-factor','POST',['code'=>app(Totp::class)->code($secret,intdiv(now()->timestamp,30))]);
check($complete->getStatusCode()===200 && str_contains($complete->getContent(),'recovery'), 'browser enrollment shows recovery codes after successful verification');
check($web('/security')->getStatusCode()===200 && isset($webCookies['remembered_email']), 'browser enrollment completes normal authenticated session and remember preference');

app('session')->driver()->invalidate();
app('cache')->store('array')->flush();
$emailOwner = User::create(['name'=>'Required email','email'=>'required-email@example.invalid','password'=>'Example123!','is_active'=>true,'two_factor_required'=>true]);
$emailLogin = json_decode(http2fa('/api/auth/login','POST',['email'=>$emailOwner->email,'password'=>'Example123!'])->getContent(),true);
$emailSetup = http2fa('/api/auth/two-factor/enroll','POST',['method'=>'email','challenge_token'=>$emailLogin['challenge_token']]);
check($emailSetup->getStatusCode()===200 && str_contains($emailSetup->getContent(),'r***@example.invalid'), 'required owner can choose email enrollment with masked address');
$emailConfirmed = http2fa('/api/auth/two-factor/challenge','POST',['challenge_token'=>$emailLogin['challenge_token'],'code'=>lastEmailCode()]);
check($emailConfirmed->getStatusCode()===200 && app(TwoFactorService::class)->status($emailOwner)['method']==='email', 'required email owner receives credentials only after email code verification');
